"""Regenerate the HTTP module catalog using an isolated fake session only."""
from pathlib import Path
import json
import os
import sys
import tempfile

REPO = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(REPO))


def generate():
    from pyrpl_websocket.lockbox import LockboxState
    from pyrpl_websocket.session import WebSession
    from pyrpl_websocket.settings import ServerSettings

    lines = ["HTTP instrument catalog", "=======================", "",
             "Generated by ``scripts/generate_http_api_reference.py`` from fake hardware.",
             "Examples show defaults, not the connected board's settings. Query the live",
             "attribute/action endpoints for calibrated values and installed custom models.",
             "See :doc:`http_api` for requests, envelopes, control ownership, and the PC client.", ""]

    def section(title, marker="-"):
        lines.extend([title, marker * len(title), ""])

    def block(value):
        lines.extend([".. code-block:: json", ""])
        lines.extend("   " + line for line in json.dumps(value, indent=2, ensure_ascii=True).splitlines())
        lines.append("")

    def attributes(items):
        if not items:
            lines.extend(["No editable attributes.", ""])
            return
        lines.extend([".. list-table:: Attributes", "   :header-rows: 1", "",
                      "   * - Name", "     - Type", "     - Default / constraints"])
        for item in items:
            constraint = {key: value for key, value in item.items()
                          if key not in {"name", "label", "type"}}
            lines.extend([f"   * - ``{item['name']}``", f"     - {item['type']}",
                          "     - ``" + json.dumps(constraint, ensure_ascii=True) + "``"])
        lines.append("")

    with tempfile.TemporaryDirectory(prefix="pyrpl-http-docs-") as directory:
        previous = os.environ.get("PYRPL_USER_DIR")
        os.environ["PYRPL_USER_DIR"] = directory
        session = None
        try:
            session = WebSession(ServerSettings(hostname="_FAKE_", curve_dir=directory + "/curves"))
            for module in session.modules():
                name = module["name"]
                section(name)
                lines.extend([module.get("description", ""), ""])
                try:
                    attributes(session.module_attributes(name))
                except KeyError:
                    lines.extend(["Use the dedicated Lockbox schema below for its controls.", ""])
                lines.extend(["Actions returned by the discovery endpoint:", ""])
                block(session.module_actions(name))
                if name != "lockbox":
                    lines.extend(["Example ``state`` inside the module response:", ""])
                    block(session.module_state(name))
            section("Additional response examples")
            for title, value in [
                ("IIR plot (8 requested points)", session.iir_plot(8)),
                ("Lockbox input model plot", session.lockbox_input_plot("input_from_output", 8)),
                ("Lockbox output transfer function", session.lockbox_output_transfer_function("output1", 8)),
            ]:
                section(title, "~")
                block(value)
            section("Lockbox models")
            lines.extend(["These schemas describe bundled model defaults. Trusted custom code can add",
                          "controls/actions at runtime. State ordering fields are illustrative here.", ""])
            for model in session.lockbox_classes():
                section(model["name"], "~")
                state = LockboxState(model["name"], library=session.lockbox.library)
                schema = state.schema()
                schema["schema_epoch"], schema["revision"] = "example-server-epoch", 1
                # Paths are installation-specific; omit class inventory repetitions.
                schema.pop("classes", None)
                block(schema)
        finally:
            if session is not None:
                session.close()
            if previous is None:
                os.environ.pop("PYRPL_USER_DIR", None)
            else:
                os.environ["PYRPL_USER_DIR"] = previous
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    destination = REPO / "docs/source/http_api_catalog.rst"
    destination.write_text(generate(), encoding="utf-8", newline="\n")
    print(destination)
